import { randomBytes } from "node:crypto";
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";

async function main() {
  const envPath = path.resolve(process.cwd(), ".env.local");

  if (!existsSync(envPath)) {
    const secret = randomBytes(48).toString("base64url");
    const contents = [
      "# Generated by `npm run db:setup` for local development.",
      "# This file is ignored by Git. Replace values for a real deployment.",
      `ROOMRELAY_SESSION_SECRET=${secret}`,
      "ROOMRELAY_CAMPUS_TIMEZONE=Europe/London",
      "",
      "# DATABASE_URL and DATABASE_URL_UNPOOLED are provided by `neon env pull`.",
      "",
    ].join("\n");

    writeFileSync(envPath, contents, { mode: 0o600 });
    console.log("Created .env.local with a local-only session secret.");
  }

  await import("./load-env");

  const [
    { getCampusTimezone, getDatabaseUrl, getSessionSecret },
    { openDatabase },
    { runMigrations },
    { seedDatabase },
  ] = await Promise.all([
    import("@/lib/config"),
    import("@/lib/db/client"),
    import("@/lib/db/migrate"),
    import("@/lib/db/seed"),
  ]);

  getSessionSecret();
  getCampusTimezone();

  const db = openDatabase(getDatabaseUrl());

  try {
    const applied = await runMigrations(db);
    const summary = await seedDatabase(db);

    console.log("Database: Postgres");
    console.log(
      applied.length > 0
        ? `Applied migrations: ${applied.join(", ")}`
        : "Migrations already up to date.",
    );
    console.table(summary);
  } finally {
    await db.close();
  }
}

main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});
